// ACSM metabolic equations: walking VO2 = 0.1*S + 1.8*S*G + 3.5; running VO2 = 0.2*S + 0.9*S*G + 3.5 (S in m/min, G as a fraction); about 5 kcal per liter of O2.
const kcalc = `<form class="calc" id="calc" onsubmit="return false"><div class="calc-in"><label>Speed (mph)<input id="k-speed" type="number" min="0.5" max="12" step="0.1" value="3"></label><label>Incline (%)<input id="k-grade" type="number" min="0" max="40" step="0.5" value="0"></label><label>Time (minutes)<input id="k-min" type="number" min="1" max="300" step="1" value="30"></label><label>Body weight<input id="k-wt" type="number" min="30" max="500" step="1" value="170"></label><label>Weight unit<select id="k-unit"><option value="lb">pounds</option><option value="kg">kilograms</option></select></label><label>Equation<select id="k-mode"><option value="walk">Walking</option><option value="run">Running or jogging</option></select></label></div><div class="calc-out" aria-live="polite"><div><span>Total calories</span><b id="k-total">0</b></div><div><span>Above resting</span><b id="k-net">0</b></div><div><span>Per hour</span><b id="k-hr">0</b></div><div><span>Intensity</span><b id="k-met">0</b></div></div><p class="calc-note" id="k-note"></p></form>`;
const kscript = `(function(){var g=function(i){return document.getElementById(i)};function run(){var mph=+g('k-speed').value||0,gr=(+g('k-grade').value||0)/100,mins=+g('k-min').value||0,w=+g('k-wt').value||0,kg=g('k-unit').value==='kg'?w:w*0.453592,run=g('k-mode').value==='run',s=mph*26.8224;var vo2=run?(0.2*s+0.9*s*gr+3.5):(0.1*s+1.8*s*gr+3.5);var total=vo2*kg/1000*5*mins,net=(vo2-3.5)*kg/1000*5*mins,hr=vo2*kg/1000*5*60;g('k-total').textContent=Math.round(total)+' kcal';g('k-net').textContent=Math.round(net)+' kcal';g('k-hr').textContent=Math.round(hr)+' kcal';g('k-met').textContent=(vo2/3.5).toFixed(1)+' METs';var msg='ACSM '+(run?'running':'walking')+' equation. Estimate only.';if(!run&&mph>3.7)msg+=' The walking equation is meant for speeds up to about 3.7 mph; for faster speeds switch to the running equation.';if(run&&mph<3)msg+=' The running equation is meant for jogging or running, so use the walking equation at slow speeds.';g('k-note').textContent=msg}['k-speed','k-grade','k-min','k-wt','k-unit','k-mode'].forEach(function(i){g(i).addEventListener('input',run);g(i).addEventListener('change',run)});run()})();`;
